llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Esaxerenone, a close biaryl amide analogue with an ortho-methyl and trifluoromethylphenyl motif, has an absolute oral bioavailability of approximately 90% in healthy subjects, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Elinzanetant, which combines a pyridine-morpholine system, an amide, and trifluoromethylated aryl groups similar to the query, has a dose-independent oral bioavailability of 36.7%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Glasdegib, a heteroaryl amide/urea with a basic piperazine, shows high absolute oral bioavailability of 77.12%, supporting that amide-containing lipophilic heterocycles can achieve F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Nilotinib, a lipophilic amide/pyridine with trifluoromethyl and poor solubility, has an estimated absolute bioavailability of ~17% in patients, representing solubility-limited low-F risk relevant to the query's high logD.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Isradipine has systemic availability of only ~16.5% in healthy volunteers due to first-pass metabolism, a low-F example; however, its dihydropyridine ester scaffold is less aligned with the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence, including the structurally close esaxerenone (F≈90%) and elinzanetant (F≈37%), supports F≥20%; the low-F analogues (nilotinib, isradipine) are either less aligned or reflect solubility/metabolic liabilities that do not override the direct high-F measurements.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule",
    "Solubility and permeability of the exact trifluoromethoxy/morpholine combination are not experimentally characterized",
    "First-pass metabolism and transporter effects for the query are unknown"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

